using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    public string recovery_id(Control o){var session=Session(o);if(!session.HasMeta("audio_recovery_id"))session.SetMeta("audio_recovery_id",NewAudioId());return session.GetMeta("audio_recovery_id").AsString();}
    public bool recovery_safe(Control o)
    {
        var session=o.Get("session").AsGodotObject();if(session==null||session.Get("document").AsGodotObject()==null)return false;return session.Get("_before").VariantType==Variant.Type.Nil&&!Recording(o).Get("active").AsBool()&&!Recording(o).Call("has_pending").AsBool()&&!Field<Node>(o,"recorder").Get("recording").AsBool()&&!o.Get("_record_busy").AsBool()&&o.Get("_record_phase").AsString()=="idle";
    }
    public void recovery_tick(Control o)
    {
        long now=unchecked((long)Time.GetTicksMsec());var session=Session(o);var document=Document(o);long revision=session.Get("revision").AsInt64();if(session==o.Get("_recovery_seen_session").AsGodotObject()&&document!=o.Get("_recovery_seen_document").AsGodotObject()&&!session.Get("dirty").AsBool()&&session.HasMeta("audio_recovery_id"))session.RemoveMeta("audio_recovery_id");if(session!=o.Get("_recovery_seen_session").AsGodotObject()||document!=o.Get("_recovery_seen_document").AsGodotObject()||revision!=o.Get("_recovery_seen_revision").AsInt64()){o.Set("_recovery_seen_session",session);o.Set("_recovery_seen_document",document);o.Set("_recovery_seen_revision",revision);o.Set("_recovery_quiet_since",now);}if(!recovery_safe(o)||!session.Get("dirty").AsBool()||now-o.Get("_recovery_quiet_since").AsInt64()<2000||now-o.Get("_recovery_last_at").AsInt64()<15000)return;queue_recovery_checkpoint(o,false);
    }
    public void queue_recovery_checkpoint(Control o,bool manual)
    {
        if(!recovery_safe(o)){if(manual)notice(o,"Finish the current gesture, automation pass or recording before creating a checkpoint.");return;}if(!Session(o).Get("dirty").AsBool()){if(manual)notice(o,"There are no unsaved edits to checkpoint.");return;}var jobs=Field<Node>(o,"_recovery_jobs");if(jobs.Call("busy").AsBool()){if(manual)notice(o,"Recovery is busy. Try again when the current operation finishes.");return;}string key=recovery_id(o);long revision=Session(o).Get("revision").AsInt64();var attempts=Dict(o,"_recovery_attempts");if(!manual&&Get(attempts,key,-1).AsInt64()==revision)return;using var recovery=new AudioRecoveryOperations();var frozen=recovery.freeze(Document(o) as Resource);string error=Get(frozen,"error","").AsString();var status=Field<Label>(o,"_recovery_status");if(error.Length>0){attempts[key]=revision;status.Text="Recovery: not saved (review status)";status.TooltipText=error;if(manual)notice(o,error);return;}var snapshot=frozen["document"].As<Resource>();string path=o.Get("document_path").AsString();var store=Field<RefCounted>(o,"_recovery_store");attempts[key]=revision;o.Set("_recovery_last_at",Time.GetTicksMsec());o.Set("_recovery_checkpoint_context",new Settings{["session"]=key,["revision"]=revision});status.Text="Recovery: saving checkpoint…";jobs.Call("request","checkpoint",Callable.From<RefCounted,Variant>(work=>{var result=store.Call("checkpoint",snapshot,key,revision,path,work).AsGodotDictionary();result["session"]=key;result["revision"]=revision;return result;}),revision);
    }
    public bool recovery_context_current(Control o,Settings context)=>o.IsInsideTree()&&o.IsVisibleInTree()&&Get(context,"owner").AsGodotObject()==Session(o)&&Get(context,"document").AsGodotObject()==Document(o)&&Get(context,"revision",-1).AsInt64()==Session(o).Get("revision").AsInt64()&&Get(context,"token",-1).AsInt64()==o.Get("_recovery_review_generation").AsInt64();
    public void close_recovery_review(Control o)
    {
        o.Set("_recovery_review_generation",o.Get("_recovery_review_generation").AsInt64()+1);var window=o.Get("_recovery_window").AsGodotObject();if(GodotObject.IsInstanceValid(window)&&(window is Node node))node.QueueFree();o.Set("_recovery_window",default(Variant));var jobs=Field<Node>(o,"_recovery_jobs");jobs.Call("cancel_kind","recovery_discover");jobs.Call("cancel_kind","recovery_restore");
    }
    public void review_recovery(Control o)
    {
        var jobs=Field<Node>(o,"_recovery_jobs");if(jobs.Call("busy").AsBool()){notice(o,"Recovery is busy. Try again when the current operation finishes.");return;}close_recovery_review(o);var context=new Settings{["owner"]=Session(o),["document"]=Document(o),["revision"]=Session(o).Get("revision"),["token"]=o.Get("_recovery_review_generation")};var store=Field<RefCounted>(o,"_recovery_store");jobs.Call("request","recovery_discover",Callable.From<RefCounted,Variant>(_=>new Settings{["context"]=context,["entries"]=store.Call("discover")}),context["token"].AsInt64());
    }
    public void show_recovery_entries(Control o,Settings context,GArray entries)
    {
        if(!recovery_context_current(o,context))return;var dialog=window(o,"Review audio recovery",new Vector2I(760,520));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();o.Set("_recovery_window",windowNode);windowNode.CloseRequested+=()=>close_recovery_review(o);label(host,"Checkpoints contain committed edits only. In-progress capture and edits since the last checkpoint may be absent. External media stays at its original path; embedded PCM WAV/MP3 audio is shared in recovery storage. Corrupt entries are left intact and cannot be restored.");if(entries.Count==0){label(host,"No recovery checkpoints were found.");ActionButton(host,"Close",()=>close_recovery_review(o));return;}var list=new ItemList{SizeFlagsVertical=Control.SizeFlags.ExpandFill};host.AddChild(list);var details=label(host,"");details.CustomMinimumSize=new Vector2(0,100);var restore=ActionButton(host,"Restore selected as new unsaved composition",()=>{var selected=list.GetSelectedItems();if(selected.Length>0)request_recovery_restore(o,context,entries[selected[0]].AsGodotDictionary());});restore.Disabled=true;foreach(var raw in entries){var entry=raw.AsGodotDictionary();string stamp=Time.GetDatetimeStringFromUnixTime(Get(entry,"time",0).AsInt64())+" UTC";list.AddItem(Get(entry,"error","").AsString().Length==0?Get(entry,"title","Damaged checkpoint").AsString()+" · "+stamp+" · r"+Get(entry,"revision","?").ToString():"Unavailable: "+entry["id"].AsString());}list.ItemSelected+=index=>{var entry=entries[(int)index].AsGodotDictionary();string error=Get(entry,"error","").AsString();var missing=PackedStrings(Get(entry,"missing_assets",Array.Empty<string>()));details.Text=error.Length>0?error:"Original: "+Get(entry,"source_path","(unsaved composition)").AsString()+"\nRevision "+entry["revision"].AsInt64()+" · "+missing.Length+" missing external source(s). Metadata, edits and source paths are preserved. Restore does not overwrite or re-save the original. Save or close your current unsaved edits first.";restore.Disabled=error.Length>0||Session(o).Get("dirty").AsBool()||!recovery_safe(o);};ActionButton(host,"Cancel",()=>close_recovery_review(o));
    }
    public void request_recovery_restore(Control o,Settings context,Settings entry)
    {
        if(!recovery_context_current(o,context)||!recovery_safe(o)){notice(o,"Finish the current interaction, then review recovery again.");return;}if(Session(o).Get("dirty").AsBool()){notice(o,"Save your current unsaved composition before restoring recovery. No work was replaced.");return;}var jobs=Field<Node>(o,"_recovery_jobs");if(jobs.Call("busy").AsBool())return;string error=Get(entry,"error","").AsString();if(error.Length>0){notice(o,error);return;}string id=Get(entry,"id","").AsString();var store=Field<RefCounted>(o,"_recovery_store");jobs.Call("request","recovery_restore",Callable.From<RefCounted,Variant>(_=>{var result=store.Call("restore",id).AsGodotDictionary();result["context"]=context;return result;}),context["token"].AsInt64());
    }
    public void recovery_completed(Control o,string kind,long generation,Variant value)
    {
        if(value.VariantType!=Variant.Type.Dictionary)return;var result=value.AsGodotDictionary();var status=Field<Label>(o,"_recovery_status");if(kind=="checkpoint"){var context=Dict(o,"_recovery_checkpoint_context");o.Set("_recovery_checkpoint_context",new Settings());if(Get(result,"session",Get(context,"session","")).AsString()!=recovery_id(o))return;string error=Get(result,"error","").AsString();status.Text=error.Length>0?"Recovery: not saved (review status)":"Recovery: checkpoint saved";status.TooltipText=error.Length>0?error:"Committed revision "+result["revision"].AsInt64()+" was checkpointed. Newer edits may not yet be included. Original composition files are untouched.";}else if(kind=="recovery_discover"){var context=Get(result,"context",new Settings()).AsGodotDictionary();if(recovery_context_current(o,context))show_recovery_entries(o,context,Get(result,"entries",new GArray()).AsGodotArray());}else if(kind=="recovery_restore"){var context=Get(result,"context",new Settings()).AsGodotDictionary();if(!recovery_context_current(o,context)||!recovery_safe(o)||Session(o).Get("dirty").AsBool()){notice(o,"The active composition changed. Recovery was not opened; your work is intact.");return;}string error=Get(result,"error","").AsString();if(error.Length>0){notice(o,error);return;}var recovered=Get(result,"document").AsGodotObject();if(recovered==null){notice(o,"The recovery document could not be decoded.");return;}close_recovery_review(o);var previous=Session(o);o.Call("open_source",recovered,new Settings{["path"]="",["document_path"]=""});if(Session(o)==previous)return;Session(o).Set("dirty",true);o.EmitSignal("document_changed");refresh_all(o);status.Text="Recovery: restored unsaved copy";Field<Label>(o,"status").Text="Recovered as an unsaved composition. Choose Save to create a new file.";var missing=PackedStrings(Get(result,"missing_assets",Array.Empty<string>()));if(missing.Length>0)notice(o,"The composition was recovered, but "+missing.Length+" external audio source(s) are missing. Their paths and clip edits were preserved. Use Relink Source before playback/export.\n"+string.Join("\n",missing));}
    }
}
